from fractions import Fraction
from math import ceil as _ceil
from typing import Optional

def two_point_reliability_fit(m1: Fraction, R1: Fraction, m2: Fraction, R2: Fraction,
                              target: Fraction) -> dict:
    """Fit R^2(m) = V/(V+F+sigma/m) through two cells, exactly in rational arithmetic."""
    if not 0 < m1 < m2:
        raise ValueError("need 0 < m1 < m2")
    gamma = (m2 / R2 - m1 / R1) / (m2 - m1)          # 1/ceiling
    nu = m1 * (1 / R1 - gamma)                       # sigma/V
    if gamma < 1 or nu < 0:
        return {"valid": False}
    ceiling = 1 / gamma
    m_star: Optional[int] = None
    if target < ceiling:
        m_star = _ceil(nu / (1 / target - gamma))
    k = m2 / m1
    sb = k * R1 / (1 + (k - 1) * R1)                 # Spearman-Brown prophecy
    return {"valid": True, "ceiling": ceiling, "F_over_V": gamma - 1,
            "sigma_over_V": nu, "min_relations": m_star,
            "spearman_brown": sb, "floor_forced": R2 < sb}

if __name__ == "__main__":
    out = two_point_reliability_fit(Fraction(80), Fraction(41, 100), Fraction(240),
                                    Fraction(3, 5), Fraction(7, 10))
    print(out)   # ceiling 82/105, sigma/V 3800/41, min_relations 626, floor_forced True

from typing import Sequence

def diagnose_miscalibration(ms: Sequence[float], slopes: Sequence[float],
                            tol: float = 5e-4) -> dict:
    """Separate relation-count noise from drift + fixed noise using
    slope(m) = cV/(V+E0+sigma/m), i.e. 1/slope is affine in 1/m."""
    if len(ms) != len(slopes) or len(ms) < 2:
        raise ValueError("need at least two (m, slope) pairs")
    if max(slopes) - min(slopes) <= tol:
        return {"relation_noise": 0.0, "asymptotic_slope": sum(slopes) / len(slopes),
                "verdict": "stable slope: deficit is scale drift + fixed noise"}
    xs = [1 / m for m in ms]; ys = [1 / s for s in slopes]
    n = len(xs); mx = sum(xs) / n; my = sum(ys) / n
    b = sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / sum((x - mx) ** 2 for x in xs)
    a = my - b * mx
    return {"asymptotic_slope": 1 / a,           # cV/(V+E0)
            "relation_noise_over_cV": b,         # sigma/(cV)
            "verdict": "slope moves with m: relation noise present"}

if __name__ == "__main__":
    print(diagnose_miscalibration([80, 240], [0.896, 0.912]))   # bit length 48
    print(diagnose_miscalibration([80, 240], [0.834, 0.834]))   # bit length 52

from typing import Sequence

def _mean(x: Sequence[float]) -> float:
    return sum(x) / len(x)

def _cov(x: Sequence[float], y: Sequence[float]) -> float:
    mx, my = _mean(x), _mean(y)
    return sum((a - mx) * (b - my) for a, b in zip(x, y))

def partialled_feature_test(dial: Sequence[float], dN: Sequence[float],
                            y: Sequence[float], t_obs: float) -> dict:
    """Frisch-Waugh-Lovell: coefficient of d(N) beyond the dial, plus the
    partial-R^2 lower bound tau^2/(tau^2+df) implied by |t| >= t_obs."""
    a, b, d = _cov(dial, dial), _cov(dial, dN), _cov(dN, dN)
    D = a * d - b * b
    if a == 0 or D == 0:
        raise ValueError("degenerate design")
    beta2 = (a * _cov(dN, y) - b * _cov(dial, y)) / D
    r = [v - (b / a) * u for u, v in zip(dial, dN)]      # residual of d(N) on dial
    slope_r = _cov(r, y) / _cov(r, r)                    # equals beta2 exactly
    df = len(y) - 3
    return {"beta2": beta2, "slope_on_residual": slope_r,
            "independent_signal": _cov(r, y) != 0,
            "partial_R2_lower_bound": t_obs ** 2 / (t_obs ** 2 + df), "df": df}

if __name__ == "__main__":
    import random
    rng = random.Random(1)
    u = [rng.gauss(0, 1) for _ in range(80)]
    v = [0.6 * a + rng.gauss(0, 1) for a in u]
    y = [0.8 * a + 0.3 * b + rng.gauss(0, 0.7) for a, b in zip(u, v)]
    print(partialled_feature_test(u, v, y, 3.92))
